export function createController(client){
  let view={query:null,items:[],total:0,pending:false,error:null,selectedIds:[]};
  let backstack=[],edits=[],retry=null;
  let abort=new AbortController();const records=new Map();
  const copy=x=>structuredClone(x);
  const publish=(changes)=>{view={...view,...changes};};
  const remember=items=>items.forEach(item=>records.set(item.id,copy(item)));
  const paint=item=>{records.set(item.id,copy(item));publish({items:view.items.map(row=>row.id===item.id?copy(item):row)});};
  async function query(parameters,rememberHistory){
    if(!parameters||typeof parameters.filter!=='string'||!Number.isInteger(parameters.page)||parameters.page<1||!Number.isInteger(parameters.pageSize)||parameters.pageSize<1||!['name-asc','value-desc'].includes(parameters.sort))throw Error('Invalid query');
    if(rememberHistory&&view.query)backstack=[...backstack,copy(view.query)];
    abort.abort();const next=new AbortController();abort=next;
    publish({query:copy(parameters),pending:true,error:null});
    try{const result=await client.search(copy(parameters),next.signal);if(next.signal.aborted)return;
      remember(result.items);publish({items:copy(result.items),total:result.total});
    }catch(error){if(!next.signal.aborted)publish({error:String(error)});throw error;
    }finally{if(!next.signal.aborted)publish({pending:false});}
  }
  async function save(id,patch,journal=true){
    if(!records.has(id)){const result=await client.search({filter:'',page:1,pageSize:Number.MAX_SAFE_INTEGER,sort:'name-asc'});remember(result.items);}
    const previous=records.get(id);if(!previous)throw Error('Unknown record');
    const before=copy(previous);abort.abort();publish({pending:false,error:null});paint({...before,...copy(patch)});
    try{const after=await client.update(id,copy(patch));paint(after);if(journal)edits=[...edits,{id,before,after:copy(after)}];retry=null;
    }catch(error){paint(before);publish({error:String(error)});retry={id,patch:copy(patch)};throw error;}
  }
  return{
    search:parameters=>query(parameters,true),state:()=>copy(view),
    select(id){publish({selectedIds:[...new Set([...view.selectedIds,id])]});},
    async back(){if(!backstack.length)return;const previous=backstack.at(-1);backstack=backstack.slice(0,-1);await query(previous,false);},
    update:(id,patch)=>save(id,patch),
    async retry(){if(!retry)throw Error('No failed operation');const operation=copy(retry);await save(operation.id,operation.patch);},
    async undo(){if(!edits.length)return false;const operation=edits.at(-1);await save(operation.id,operation.before,false);edits=edits.slice(0,-1);return true;},
    exportJson(){return JSON.stringify({schema:'search-state-v1',view,backstack,edits,retry,records:Object.fromEntries(records)});},
    restoreJson(serialized){const data=JSON.parse(serialized);if(data.schema!=='search-state-v1'||!data.view||!Array.isArray(data.backstack)||!Array.isArray(data.edits)||!data.records)throw Error('Invalid search snapshot');abort.abort();abort=new AbortController();view={...copy(data.view),pending:false};backstack=copy(data.backstack);edits=copy(data.edits);retry=copy(data.retry);records.clear();for(const[id,row]of Object.entries(data.records))records.set(id,copy(row));},
  };
}
